INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-potential-1', 'sent-ex-potential-1', 'en', 'I can speak a little English.', 'authored'),
  ('st-ex-potential-2', 'sent-ex-potential-2', 'en', 'Can you read kanji?', 'authored'),
  ('st-ex-potential-3', 'sent-ex-potential-3', 'en', 'I can''t get up early in the morning.', 'authored'),
  ('st-ex-potential-4', 'sent-ex-potential-4', 'en', 'My older brother can swim in the sea.', 'authored'),
  ('st-ex-ranuki-1', 'sent-ex-ranuki-1', 'en', 'I can go to bed early today.', 'authored'),
  ('st-ex-ranuki-2', 'sent-ex-ranuki-2', 'en', 'Children can watch that film too.', 'authored'),
  ('st-ex-ranuki-3', 'sent-ex-ranuki-3', 'en', 'I can''t get up early in the morning.', 'authored'),
  ('st-ex-ranuki-4', 'sent-ex-ranuki-4', 'en', 'I can''t eat all of it.', 'authored'),
  ('st-ex-volitional-1', 'sent-ex-volitional-1', 'en', 'Let''s go together.', 'authored'),
  ('st-ex-volitional-2', 'sent-ex-volitional-2', 'en', 'Let''s watch a film tomorrow.', 'authored'),
  ('st-ex-volitional-3', 'sent-ex-volitional-3', 'en', 'Shall we eat?', 'authored'),
  ('st-ex-volitional-4', 'sent-ex-volitional-4', 'en', 'Let''s head home soon.', 'authored'),
  ('st-ex-passive-1', 'sent-ex-passive-1', 'en', 'My name was called by the teacher.', 'authored'),
  ('st-ex-passive-2', 'sent-ex-passive-2', 'en', 'I got rained on, and it was a nuisance.', 'authored'),
  ('st-ex-passive-3', 'sent-ex-passive-3', 'en', 'My little brother ate my cake on me.', 'authored'),
  ('st-ex-passive-4', 'sent-ex-passive-4', 'en', 'That book is read by students.', 'authored'),
  ('st-ex-causative-1', 'sent-ex-causative-1', 'en', 'The teacher made the students read a book.', 'authored'),
  ('st-ex-causative-2', 'sent-ex-causative-2', 'en', 'My mother makes my little sister eat vegetables.', 'authored'),
  ('st-ex-causative-3', 'sent-ex-causative-3', 'en', 'I let the children play in the park.', 'authored'),
  ('st-ex-causative-4', 'sent-ex-causative-4', 'en', 'Please let me rest a little.', 'authored'),
  ('st-ex-causpass-1', 'sent-ex-causpass-1', 'en', 'I was made to eat vegetables by my mother.', 'authored'),
  ('st-ex-causpass-2', 'sent-ex-causpass-2', 'en', 'I was made to work long hours at the company.', 'authored'),
  ('st-ex-causpass-3', 'sent-ex-causpass-3', 'en', 'I was made to write kanji every day.', 'authored'),
  ('st-ex-causpass-4', 'sent-ex-causpass-4', 'en', 'I was kept waiting for a whole hour.', 'authored'),
  ('st-ex-tocond-1', 'sent-ex-tocond-1', 'en', 'When spring comes, the cherry blossoms bloom.', 'authored'),
  ('st-ex-tocond-2', 'sent-ex-tocond-2', 'en', 'If you push the door, it opens.', 'authored'),
  ('st-ex-tocond-3', 'sent-ex-tocond-3', 'en', 'If you turn right, there is the station.', 'authored'),
  ('st-ex-tocond-4', 'sent-ex-tocond-4', 'en', 'When you leave the station, you can see the bank.', 'authored'),
  ('st-ex-bacond-1', 'sent-ex-bacond-1', 'en', 'If I have time, I will go.', 'authored'),
  ('st-ex-bacond-2', 'sent-ex-bacond-2', 'en', 'If it''s cheap, I''ll buy it.', 'authored'),
  ('st-ex-bacond-3', 'sent-ex-bacond-3', 'en', 'If you go early, you will be in time.', 'authored'),
  ('st-ex-bacond-4', 'sent-ex-bacond-4', 'en', 'If you take the medicine, you will get better.', 'authored'),
  ('st-ex-taracond-1', 'sent-ex-taracond-1', 'en', 'When you arrive at the station, please call me.', 'authored'),
  ('st-ex-taracond-2', 'sent-ex-taracond-2', 'en', 'When I get home, I do my homework.', 'authored'),
  ('st-ex-taracond-3', 'sent-ex-taracond-3', 'en', 'When I graduate from university, I want to work in Japan.', 'authored'),
  ('st-ex-taracond-4', 'sent-ex-taracond-4', 'en', 'If I had the money, I would buy a car.', 'authored'),
  ('st-ex-naracond-1', 'sent-ex-naracond-1', 'en', 'If it is English, I can do it.', 'authored'),
  ('st-ex-naracond-2', 'sent-ex-naracond-2', 'en', 'If you are going, I will go too.', 'authored'),
  ('st-ex-naracond-3', 'sent-ex-naracond-3', 'en', 'If it''s cheap, I''ll buy it.', 'authored'),
  ('st-ex-naracond-4', 'sent-ex-naracond-4', 'en', 'If it is tomorrow, I have time.', 'authored')
