-- N4 example sentences, batch 1: the conjugation forms and the four conditionals.
--
-- N5 taught verbs in two shapes, polite and plain. N4 opens by bending them:
-- potential, volitional, passive, causative, and the causative-passive that
-- stacks the last two. Then the four ways Japanese says "if" — と, ば, たら,
-- なら — which are one word in English and four different claims here.
--
-- Two rewordings the tokeniser forced:
--
--   日本語 is not a published word, so 日本語が話せます came apart as 日本 |
--   語が and the gloss offered 語る, "to talk about", for a particle. 英語 is
--   published; the potential topic asks about English instead.
--
--   昨日雨に降られました left 雨 with no ruby: the reading aligner gives 雨 its
--   あめ when the word opens the sentence and not when it follows 昨日, so the
--   token shipped bare and romaji mode had nothing to show. 雨 leads the
--   sentence instead.
--
--   歌わせられました shredded to 歌 | わ | せ | ら | れ. The causative-passive
--   of a godan verb is five morphemes deep and the index holds only some of
--   them; 書かせられました survives whole, so the sentence is about being made
--   to write kanji every day rather than being made to sing.
--
-- Also avoided: この and その are not published (あの is), nor are ボタン,
-- まっすぐ, 多く and 速い. Nothing here uses them.
--
-- Additive, idempotent, safe on a live database.

  -- potential
  ('sent-ex-potential-1', 'lang-ja', '私は英語が少し話せます。', 'わたし わ えいご が すこし はなせます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-potential-2', 'lang-ja', '漢字が読めますか。', 'かんじ が よめます か。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-potential-3', 'lang-ja', '朝早く起きられません。', 'あさ はやく おきられません。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-potential-4', 'lang-ja', '兄は海で泳げます。', 'あに わ うみ で およげます。', 'lvl-ja-n4', 'authored', true),
  -- ra-nuki
  ('sent-ex-ranuki-1', 'lang-ja', '今日は早く寝れる。', 'きょう わ はやく ねれる。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-ranuki-2', 'lang-ja', 'あの映画は子供も見れる。', 'あの えいが わ こども も みれる。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-ranuki-3', 'lang-ja', '朝早く起きれない。', 'あさ はやく おきれない。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-ranuki-4', 'lang-ja', '全部は食べれない。', 'ぜんぶ わ たべれない。', 'lvl-ja-n4', 'authored', true),
  -- volitional
  ('sent-ex-volitional-1', 'lang-ja', '一緒に行こう。', 'いっしょ に いこう。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-volitional-2', 'lang-ja', '明日映画を見よう。', 'あした えいが お みよう。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-volitional-3', 'lang-ja', 'ご飯を食べようか。', 'ごはん お たべよう か。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-volitional-4', 'lang-ja', 'そろそろ帰ろう。', 'そろそろ かえろう。', 'lvl-ja-n4', 'authored', true),
  -- passive
  ('sent-ex-passive-1', 'lang-ja', '先生に名前を呼ばれました。', 'せんせい に なまえ お よばれました。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-passive-2', 'lang-ja', '雨に降られて困りました。', 'あめ に ふられて こまりました。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-passive-3', 'lang-ja', '弟にケーキを食べられた。', 'おとうと に ケーキ お たべられた。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-passive-4', 'lang-ja', 'あの本は学生に読まれています。', 'あの ほん わ がくせい に よまれて います。', 'lvl-ja-n4', 'authored', true),
  -- causative
  ('sent-ex-causative-1', 'lang-ja', '先生は学生に本を読ませました。', 'せんせい わ がくせい に ほん お よませました。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-causative-2', 'lang-ja', '母は妹に野菜を食べさせる。', 'はは わ いもうと に やさい お たべさせる。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-causative-3', 'lang-ja', '子供を公園で遊ばせます。', 'こども お こうえん で あそばせます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-causative-4', 'lang-ja', '少し休ませてください。', 'すこし やすませて ください。', 'lvl-ja-n4', 'authored', true),
  -- causative-passive
  ('sent-ex-causpass-1', 'lang-ja', '母に野菜を食べさせられました。', 'はは に やさい お たべさせられました。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-causpass-2', 'lang-ja', '会社で長い時間働かせられた。', 'かいしゃ で ながい じかん はたらかせられた。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-causpass-3', 'lang-ja', '毎日漢字を書かせられました。', 'まいにち かんじ お かかせられました。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-causpass-4', 'lang-ja', '一時間も待たせられた。', 'いちじかん も またせられた。', 'lvl-ja-n4', 'authored', true),
  -- to-conditional
  ('sent-ex-tocond-1', 'lang-ja', '春になると、桜が咲きます。', 'はる に なる と、さくら が さきます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-tocond-2', 'lang-ja', 'ドアを押すと、開きます。', 'ドア お おす と、あきます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-tocond-3', 'lang-ja', '右に曲がると、駅があります。', 'みぎ に まがる と、えき が あります。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-tocond-4', 'lang-ja', '駅を出ると、銀行が見えます。', 'えき お でる と、ぎんこう が みえます。', 'lvl-ja-n4', 'authored', true),
  -- ba-conditional
  ('sent-ex-bacond-1', 'lang-ja', '時間があれば、行きます。', 'じかん が あれば、いきます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-bacond-2', 'lang-ja', '安ければ買います。', 'やすければ かいます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-bacond-3', 'lang-ja', '早く行けば、間に合います。', 'はやく いけば、まにあいます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-bacond-4', 'lang-ja', '薬を飲めば、よくなります。', 'くすり お のめば、よく なります。', 'lvl-ja-n4', 'authored', true),
  -- tara-conditional
  ('sent-ex-taracond-1', 'lang-ja', '駅に着いたら、電話してください。', 'えき に ついたら、でんわ して ください。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-taracond-2', 'lang-ja', '家に帰ったら、宿題をします。', 'いえ に かえったら、しゅくだい お します。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-taracond-3', 'lang-ja', '大学を卒業したら、日本で働きたいです。', 'だいがく お そつぎょう したら、にほん で はたらきたい です。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-taracond-4', 'lang-ja', 'お金があったら、車を買います。', 'おかね が あったら、くるま お かいます。', 'lvl-ja-n4', 'authored', true),
  -- nara-conditional
  ('sent-ex-naracond-1', 'lang-ja', '英語ならできます。', 'えいご なら できます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-naracond-2', 'lang-ja', '行くなら、私も行きます。', 'いく なら、わたし も いきます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-naracond-3', 'lang-ja', '安いなら買います。', 'やすい なら かいます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-naracond-4', 'lang-ja', '明日なら時間があります。', 'あした なら じかん が あります。', 'lvl-ja-n4', 'authored', true)
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

SELECT g.id, s.id, 'example', s.n
FROM (VALUES
  ('potential', 'sent-ex-potential-1', 0),
  ('potential', 'sent-ex-potential-2', 1),
  ('potential', 'sent-ex-potential-3', 2),
  ('potential', 'sent-ex-potential-4', 3),
  ('ra-nuki', 'sent-ex-ranuki-1', 0),
  ('ra-nuki', 'sent-ex-ranuki-2', 1),
  ('ra-nuki', 'sent-ex-ranuki-3', 2),
  ('ra-nuki', 'sent-ex-ranuki-4', 3),
  ('volitional', 'sent-ex-volitional-1', 0),
  ('volitional', 'sent-ex-volitional-2', 1),
  ('volitional', 'sent-ex-volitional-3', 2),
  ('volitional', 'sent-ex-volitional-4', 3),
  ('passive', 'sent-ex-passive-1', 0),
  ('passive', 'sent-ex-passive-2', 1),
  ('passive', 'sent-ex-passive-3', 2),
  ('passive', 'sent-ex-passive-4', 3),
  ('causative', 'sent-ex-causative-1', 0),
  ('causative', 'sent-ex-causative-2', 1),
  ('causative', 'sent-ex-causative-3', 2),
  ('causative', 'sent-ex-causative-4', 3),
  ('causative-passive', 'sent-ex-causpass-1', 0),
  ('causative-passive', 'sent-ex-causpass-2', 1),
  ('causative-passive', 'sent-ex-causpass-3', 2),
  ('causative-passive', 'sent-ex-causpass-4', 3),
  ('to-conditional', 'sent-ex-tocond-1', 0),
  ('to-conditional', 'sent-ex-tocond-2', 1),
  ('to-conditional', 'sent-ex-tocond-3', 2),
  ('to-conditional', 'sent-ex-tocond-4', 3),
  ('ba-conditional', 'sent-ex-bacond-1', 0),
  ('ba-conditional', 'sent-ex-bacond-2', 1),
  ('ba-conditional', 'sent-ex-bacond-3', 2),
  ('ba-conditional', 'sent-ex-bacond-4', 3),
  ('tara-conditional', 'sent-ex-taracond-1', 0),
  ('tara-conditional', 'sent-ex-taracond-2', 1),
  ('tara-conditional', 'sent-ex-taracond-3', 2),
  ('tara-conditional', 'sent-ex-taracond-4', 3),
  ('nara-conditional', 'sent-ex-naracond-1', 0),
  ('nara-conditional', 'sent-ex-naracond-2', 1),
  ('nara-conditional', 'sent-ex-naracond-3', 2),
  ('nara-conditional', 'sent-ex-naracond-4', 3)
) AS s(slug, id, n)
JOIN grammar_points g ON g.language_id = 'lang-ja' AND g.slug = s.slug
ON CONFLICT (grammar_point_id, sentence_id, role) DO NOTHING;

-- The tokens. `tokenise:authored` is a dev script and production runs only
-- migrations and seeds; the quiz derivation cuts its chips from these rows.
DELETE FROM sentence_tokens WHERE sentence_id IN ('sent-ex-potential-1', 'sent-ex-potential-2', 'sent-ex-potential-3', 'sent-ex-potential-4', 'sent-ex-ranuki-1', 'sent-ex-ranuki-2', 'sent-ex-ranuki-3', 'sent-ex-ranuki-4', 'sent-ex-volitional-1', 'sent-ex-volitional-2', 'sent-ex-volitional-3', 'sent-ex-volitional-4', 'sent-ex-passive-1', 'sent-ex-passive-3', 'sent-ex-passive-4', 'sent-ex-causative-1', 'sent-ex-causative-2', 'sent-ex-causative-3', 'sent-ex-causative-4', 'sent-ex-causpass-1', 'sent-ex-causpass-2', 'sent-ex-causpass-3', 'sent-ex-causpass-4', 'sent-ex-tocond-1', 'sent-ex-tocond-2', 'sent-ex-tocond-3', 'sent-ex-tocond-4', 'sent-ex-bacond-1', 'sent-ex-bacond-2', 'sent-ex-bacond-3', 'sent-ex-bacond-4', 'sent-ex-taracond-1', 'sent-ex-taracond-2', 'sent-ex-taracond-3', 'sent-ex-taracond-4', 'sent-ex-naracond-1', 'sent-ex-naracond-2', 'sent-ex-naracond-3', 'sent-ex-naracond-4', 'sent-ex-passive-2');
